package org.openrow.probe;

import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Packet-rate independence, lifecycle, receipts, migration, and crash boundaries. */
public final class WorkoutRecordingTest {
    static int checks;
    static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
    static void near(double actual,double expected){check(Math.abs(actual-expected)<.00001,actual+" != "+expected);}
    static RowingTelemetryFrame frame(long at,double meters,double watts){return new RowingTelemetryFrame(at,true,at,meters,at,watts,2,24,-1,Double.NaN,Double.NaN,0,Double.NaN,"S4 estimated watts");}
    static WorkoutSession row(String id){WorkoutSession s=new WorkoutSession(id,"Standalone rowing",100);s.block=0;s.resume(0);for(int i=0;i<=20;i++){s.accept(frame(i*500,i,100),i%5==0);s.sample(i*500);}return s;}
    static Properties power(String id,double watts,long ended){Properties p=new Properties();p.setProperty("id",id);p.setProperty("finished","true");p.setProperty("ended",""+ended);p.setProperty("effort","5");p.setProperty("athlete.powerSeconds","90");p.setProperty("athlete.motionSeconds","100");p.setProperty("athlete.energyJ",""+(watts*90));return p;}
    public static void main(String[] args)throws Exception{
        WorkoutSession s=row("one");near(s.total("distance"),20);near(s.total("energyJ"),950);near(s.total("powerSeconds"),9.5);near(s.total("strokes"),5);near(s.total("motionSeconds"),9.5);
        double joules=s.total("energyJ");s.accept(frame(10000,20,100),false);near(s.total("energyJ"),joules);s.pause(10000);s.accept(frame(20000,100,200),true);near(s.total("distance"),20);near(s.total("strokes"),5);
        s.resume(20000);s.accept(frame(20000,100,100),false);s.accept(frame(20500,101,100),false);near(s.total("distance"),21);near(s.total("energyJ"),joules);s.accept(frame(21000,102,100),false);near(s.total("energyJ"),joules+50);
        s.accept(frame(21500,0,100),false);s.accept(frame(22000,1,100),false);near(s.total("distance"),23);
        s.accept(frame(30000,200,100),false);near(s.total("distance"),23);check(!s.moving(30000),"No movement inferred across gap");
        s.accept(new RowingTelemetryFrame(31000,false,-1,Double.NaN,-1,Double.NaN,Double.NaN,Double.NaN,-1,Double.NaN,Double.NaN,0,Double.NaN,"Disconnected"),true);check(s.paused(),"Disconnect pauses");
        s.finish(32000,1000);near(s.total("workouts"),1);s.resume(33000);check(s.paused(),"Finished cannot resume");
        AthleteHistory history=new AthleteHistory();history.syncSession(s.credit());double total=history.value("total.distance");history.syncSession(s.credit());near(history.value("total.distance"),total);near(history.value("total.workouts"),1);history.resetTotals(2000);history.syncSession(s.credit());near(history.value("total.distance"),0);check(history.value("last.ended")==0,"Reset does not resurrect last workout");
        Properties legacy=new Properties();legacy.setProperty("game.v4","42");legacy.setProperty("game.counts","90,7");legacy.setProperty("game.sessionMotion","12");legacy.setProperty("game.v6","15");legacy.setProperty("session.stats.energyJ","200");WorkoutSession migrated=new WorkoutSession("legacy-one","Gravity Well",10);migrated.migrate(legacy);near(migrated.total("distance"),42);near(migrated.number("elapsed"),15);near(Double.parseDouble(migrated.credit().getProperty("athlete.distance")),0);migrated.resume(0);migrated.accept(frame(0,100,100),false);migrated.accept(frame(500,101,100),false);near(Double.parseDouble(migrated.credit().getProperty("athlete.distance")),1);migrated.finish(1000,4000);near(Double.parseDouble(migrated.credit().getProperty("athlete.workouts")),1);
        Path root=Files.createTempDirectory(Paths.get("build"),"workout-test-");WorkoutStore store=new WorkoutStore(root.toFile());WorkoutSession first=row("first");store.save(first);long bytes=(long)first.number("bytes");check(bytes>0,"Timeline committed");near(store.samples("first").size(),11);
        try(FileOutputStream append=new FileOutputStream(root.resolve("workouts/first.csv").toFile(),true)){append.write("uncommitted-tail".getBytes("UTF-8"));}
        WorkoutStore restarted=new WorkoutStore(root.toFile());WorkoutSession restored=restarted.active();check(restored.paused(),"Restored paused");near(restored.total("distance"),20);restored.resume(0);restored.sample(0);restarted.save(restored);check(!new String(Files.readAllBytes(root.resolve("workouts/first.csv")),"UTF-8").contains("uncommitted"),"Torn append removed");
        restored.finish(1000,5000);restarted.save(restored);check(restarted.active()==null,"Finish clears pointer");check(restarted.history().size()==1,"One history entry");
        WorkoutSession second=row("second");restarted.save(second);restarted.save(restored);check(restarted.active().id().equals("second"),"Editing old history preserves active pointer");
        Properties old=new Properties();old.setProperty("id","old");WorkoutStore.atomic(root.resolve("atomic.properties").toFile(),old);Files.copy(root.resolve("atomic.properties"),root.resolve("atomic.properties.bak"));old.setProperty("id","new");WorkoutStore.atomic(root.resolve("atomic.properties").toFile(),old); // normal subsequent commit
        check(WorkoutStore.read(root.resolve("atomic.properties").toFile()).getProperty("id").equals("new"),"Atomic commit");
        boolean rejected=false;try{new WorkoutSession("../outside","bad",0);}catch(IllegalArgumentException expected){rejected=true;}check(rejected,"Traversal rejected");
        RowingMetrics metrics=new RowingMetrics();metrics.setConnected(true);metrics.accept("IV40210",0);metrics.accept("IDS00D00",0);metrics.accept("IDS04110",0);metrics.accept("IDD0880064",0);metrics.accept("IDD055000A",0);RowingTelemetryFrame f=RowingTelemetryFrame.from(metrics,500);check(f.powerAvailable(),"Verified watts");near(f.watts,100);check(!RowingTelemetryFrame.from(metrics,2000).powerAvailable(),"Stale power missing");metrics.accept("IDS04120",1000);check(!RowingTelemetryFrame.from(metrics,1000).powerAvailable(),"Calorie mode rejected");
        RowingEffortFrame.Resolver effort=new RowingEffortFrame.Resolver(100,2,true);RowingEffortFrame e=null;for(int i=0;i<30;i++)e=effort.resolve(frame(i*500,i,100),true,null);check(e.source.equals("Power"),"Power after 3 readings");check(e.contribution>.99&&e.contribution<=1.25,"Reference effort bounded");e=effort.resolve(frame(15000,30,0),true,null);near(e.contribution,0);check(e.source.equals("Power"),"Valid zero is power");e=effort.resolve(frame(15500,31,Double.NaN),true,null);check(e.source.equals("Pace"),"Power gap fallback");check(effort.resolve(frame(16000,32,100),false,null).contribution==0,"No motion no rewards");
        RowingEffortFrame.Resolver gate=new RowingEffortFrame.Resolver(100,2,false);for(int i=0;i<10;i++)e=gate.resolve(frame(i*500,i,200),true,null);check(e.source.equals("Pace"),"Hardware validation gate");
        WorkoutSession fast=row("packet-rate");double beforeEnergy=fast.total("energyJ"),beforeCadence=fast.total("cadenceCount");for(int i=0;i<100;i++)fast.accept(frame(10000,20,100),false);near(fast.total("energyJ"),beforeEnergy);near(fast.total("cadenceCount"),beforeCadence);
        WorkoutSession gaps=row("power-gaps");double originalEnergy=gaps.total("energyJ");gaps.accept(frame(10500,21,Double.NaN),false);gaps.accept(frame(11000,22,100),false);near(gaps.total("energyJ"),originalEnergy);gaps.accept(frame(11500,23,100),false);near(gaps.total("energyJ"),originalEnergy+50);gaps.accept(frame(12000,24,0),false);gaps.accept(frame(12500,25,0),false);near(gaps.total("energyJ"),originalEnergy+75);
        TrainingCore.Plan plan=TrainingCore.assessment(TrainingCore.Kind.QUICK,TrainingCore.Category.ENDURANCE,TrainingCore.Goal.ENDURANCE);TrainingCore.Runner runner=new TrainingCore.Runner("guided",plan,1,false);runner.resume(0);runner.tick(1000,true,true);GameWorkoutAdapter.Frame warm=new GameWorkoutAdapter.Frame(runner);e=effort.resolve(frame(17000,34,100),true,warm);near(e.contribution,0);runner.pause(1000);e=effort.resolve(frame(17500,35,100),true,new GameWorkoutAdapter.Frame(runner));near(e.contribution,0);
        WorkoutSession blocks=new WorkoutSession("blocks","Gravity Well",1);blocks.block=0;blocks.phase="WARM_UP";blocks.resume(0);blocks.accept(frame(0,0,100),false);blocks.accept(frame(500,1,100),false);blocks.block=1;blocks.phase="WORK";blocks.accept(frame(1000,2,100),false);near(blocks.number("block.1.distance"),1);near(blocks.number("block.0.distance"),1);
        long now=100*TrainingCore.DAY;List<Properties> refs=new ArrayList<>();refs.add(power("a",100,now));near(RowingEffortFrame.powerReference(refs,Collections.emptyList(),now),0);refs.add(power("b",200,now));near(RowingEffortFrame.powerReference(refs,Collections.emptyList(),now),150);refs.get(1).setProperty("simulated","true");near(RowingEffortFrame.powerReference(refs,Collections.emptyList(),now),0);refs.get(1).remove("simulated");refs.get(1).setProperty("ended","1");near(RowingEffortFrame.powerReference(refs,Collections.emptyList(),now),0);
        System.out.println("PASS: "+checks+" shared telemetry, recorder, storage, receipt and effort checks");
    }
}
